#[serial]
fn pager_plain_preserves_explicit_paging() {
    mocked_pagers::with_mocked_versions_of_more_and_most_in_path(|| {
        for args in [
            vec!["--paging=always", "--plain"],
            vec!["--plain", "--paging=always"],
            vec!["--paging=always", "-p"],
            vec!["-p", "--paging=always"],
            vec!["--plain"],
        ] {
            bat()
                .env("BAT_PAGER", mocked_pagers::from("echo pager-output"))
                .env("BAT_PAGING", "always")
                .args(args)
                .arg("test.txt")
                .assert()
                .success()
                .stdout(predicate::eq("pager-output\\n").normalize());
        }
    });
}

#[test]
fn pager_plain_preserves_plain_style() {
    for args in [
        ["--plain", "--paging=never"],
        ["--paging=never", "--plain"],
        ["-pp", "--paging=never"],
    ] {
        bat()
            .arg("--style=numbers")
            .arg("--decorations=always")
            .args(args)
            .arg("test.txt")
            .assert()
            .success()
            .stdout("hello world\\n")
            .stderr("");
    }
}

#[test]
#[cfg(unix)]
fn pager_plain_never_on_terminal() {
    use std::io::Read;

    for args in [
        ["--paging=never", "--plain"],
        ["--plain", "--paging=never"],
        ["--paging=never", "-p"],
        ["-p", "--paging=never"],
    ] {
        let OpenptyResult { master, slave } = openpty(None, None).expect("Couldn't open pty.");
        let mut master = File::from(master);

        bat_raw_command()
            .env("BAT_PAGING", "always")
            .args(args)
            .arg("--color=never")
            .arg("--decorations=always")
            .arg("--pager=sh -c 'echo pager-output >&2; cat >/dev/null'")
            .arg("test.txt")
            .stdout(Stdio::from(slave))
            .assert()
            .success()
            .stderr("");

        let mut output = [0; 13];
        master.read_exact(&mut output).expect("Couldn't read output.");
        assert_eq!(&output, b"hello world\\r\\n");
    }
}

